    var so = new UnityEditor.SerializedObject(manager);
    var targetsProp = so.FindProperty("_targets");
    if (targetsProp != null)
        UnityEngine.Debug.Log($"_targets count: {targetsProp.arraySize}");
    else
        UnityEngine.Debug.Log($"_targets prop not found");

    // Check entries
    var entriesProp = so.FindProperty("_entries");
    if (entriesProp != null)
        UnityEngine.Debug.Log($"_entries count: {entriesProp.arraySize}");
    else
        UnityEngine.Debug.Log($"_entries prop not found");

    // Check pool
    var poolProp = so.FindProperty("_pool");
    if (poolProp != null)
        UnityEngine.Debug.Log($"_pool count: {poolProp.arraySize}");
    else
        UnityEngine.Debug.Log($"_pool prop not found");

    // Force register all targets
    var allTargets = UnityEngine.Object.FindObjectsOfType<Shadow2DTarget>(true);
    UnityEngine.Debug.Log($"Shadow2DTargets in scene: {allTargets.Length}");
    foreach (var t in allTargets)
    {
        UnityEngine.Debug.Log($"  Target: {t.name} enabled={t.enabled} active={t.gameObject.activeInHierarchy}");
        manager.Register(t);
    }

    // Now check children again
    int activeCount = 0;
    for (int i = 0; i < manager.transform.childCount; i++)
    {
        var child = manager.transform.GetChild(i);
        if (child.gameObject.activeSelf) activeCount++;
    }
    UnityEngine.Debug.Log($"Active shadow children after re-register: {activeCount}/{manager.transform.childCount}");
}

