        {
            // Use SerializedObject on a temp material to read pass tags
            var tempMat = new UnityEngine.Material(shader);
            var so = new UnityEditor.SerializedObject(tempMat);
            // Try to find pass tags
            var prop = so.GetIterator();
            while (prop.NextVisible(true))
            {
                if (prop.name.Contains("LightMode") || prop.name.Contains("PassName") || prop.name.Contains("m_Passes"))
                {
                    UnityEngine.Debug.Log($"  Prop: {prop.name} = {prop.stringValue}");
                }
            }
            UnityEngine.Object.DestroyImmediate(tempMat);
        }
    }
    else
