        _AlphaCutoff ("Alpha Cutoff", Range(0, 1)) = 0.1
        _PenumbraScale ("Penumbra Scale", Range(0, 0.05)) = 0.008
        _ContactBoost ("Contact Darkening", Range(0, 1)) = 0.3
    }

    SubShader
    {
        Tags
        {
            "RenderPipeline" = "UniversalPipeline"
            "Queue" = "Transparent"
            "IgnoreProjector" = "True"
            "RenderType" = "Transparent"
            "PreviewType" = "Plane"
            "CanUseSpriteAtlas" = "True"
        }

        Cull Off
        ZWrite Off
        Blend One OneMinusSrcAlpha

        Pass
        {
            Name "Default"
            Tags { "LightMode" = "Universal2D" }

        HLSLPROGRAM
            #pragma vertex vert
            #pragma fragment frag
            #pragma target 2.0
            #pragma multi_compile_instancing

            #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Core.hlsl"

            struct appdata
            {
                float4 vertex : POSITION;
                float4 color : COLOR;
                float2 uv : TEXCOORD0;
                UNITY_VERTEX_INPUT_INSTANCE_ID
            };

            struct v2f
            {
                float4 vertex : SV_POSITION;
                half4 color : COLOR;
                float2 uv : TEXCOORD0;
                UNITY_VERTEX_INPUT_INSTANCE_ID
            };

            TEXTURE2D(_MainTex);
            SAMPLER(sampler_MainTex);

            CBUFFER_START(UnityPerMaterial)
                half4 _ShadowColor;
                float _Opacity;
                float _TipFade;
                float _AlphaCutoff;
                float _PenumbraScale;
                float _ContactBoost;
            CBUFFER_END

            // Per-renderer values from Shadow2DManager via MaterialPropertyBlock.
            // _ShadowDirX/Y: normalized direction the shadow stretches toward (away from light).
            // _ShadowStretch: how much to stretch along that direction.
            // _SpriteVMin/_SpriteVInvH: atlas-safe base->tip 0..1 coordinate.
            float _ShadowDirX;
            float _ShadowDirY;
            float _ShadowStretch;
            float _SpriteVMin;
            float _SpriteVInvH;

            v2f vert(appdata v)
            {
                v2f o;
                UNITY_SETUP_INSTANCE_ID(v);
                UNITY_TRANSFER_INSTANCE_ID(v, o);

                // Stretch vertices along the shadow direction.
                // UV.y maps 0=base (contact) to 1=tip (cast end).
                // We stretch the tip away while keeping the base pinned.
                float h01 = saturate((v.uv.y - _SpriteVMin) * _SpriteVInvH);
                float2 dir = float2(_ShadowDirX, _ShadowDirY);
                float2 pos = v.vertex.xy;
                pos += dir * h01 * _ShadowStretch;

                v.vertex.xy = pos;
                o.vertex = TransformObjectToHClip(v.vertex.xyz);
                o.uv = v.uv;
                o.color = v.color;
                return o;
            }

            half SampleSilhouette(float2 uv, float radius)
            {
                half a = SAMPLE_TEXTURE2D(_MainTex, sampler_MainTex, uv).a * 0.4h;
                a += SAMPLE_TEXTURE2D(_MainTex, sampler_MainTex, uv + float2( radius, 0)).a * 0.15h;
                a += SAMPLE_TEXTURE2D(_MainTex, sampler_MainTex, uv + float2(-radius, 0)).a * 0.15h;
                a += SAMPLE_TEXTURE2D(_MainTex, sampler_MainTex, uv + float2(0,  radius)).a * 0.15h;
                a += SAMPLE_TEXTURE2D(_MainTex, sampler_MainTex, uv + float2(0, -radius)).a * 0.15h;
                return a;
            }

            half4 frag(v2f i) : SV_Target
            {
                UNITY_SETUP_INSTANCE_ID(i);

                float h01 = saturate((i.uv.y - _SpriteVMin) * _SpriteVInvH);

                float radius = _PenumbraScale * h01 * max(_ShadowStretch, 1.0);
                half texA = SampleSilhouette(i.uv, radius);
                texA *= i.color.a;
                clip(texA - _AlphaCutoff);

                // Fade toward the cast tip, darken at the contact end.
                float fade = 1.0 - smoothstep(0.2, 1.0, h01) * _TipFade;
                float contact = 1.0 - h01;
                fade *= 1.0 + _ContactBoost * contact * contact;

                half a = saturate(texA * _ShadowColor.a * _Opacity * fade);
                half3 rgb = _ShadowColor.rgb * a; // premultiplied alpha
                return half4(rgb, a);
            }
        ENDHLSL
        }
    }
}

