// Revert all shadow sprites back to the ProjectedShadow material
var manager = UnityEngine.Object.FindObjectOfType<Shadow2DManager>();
if (manager != null)
{
    var shadowMat = UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.Material>("Assets/Flynn/Materials/ProjectedShadow.mat");
    int reverted = 0;
    for (int i = 0; i < manager.transform.childCount; i++)
    {
        var child = manager.transform.GetChild(i);
        var sr = child.GetComponent<UnityEngine.SpriteRenderer>();
        if (sr != null && sr.sharedMaterial?.name != "ProjectedShadow")
        {
            sr.sharedMaterial = shadowMat;
            reverted++;
        }
    }
    UnityEngine.Debug.Log($"Reverted {reverted} shadow sprites to ProjectedShadow material");
}

