args.script:
var manager = UnityEngine.Object.FindObjectOfType<Shadow2DManager>();
var light = UnityEngine.Object.FindObjectOfType<UnityEngine.Rendering.Universal.Light2D>();
var shadowMat = UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.Material>("Assets/Flynn/Materials/ProjectedShadow.mat");

if (manager != null)
{
    var so = new UnityEditor.SerializedObject(manager);

    var lightProp = so.FindProperty("_lightSource");
    if (lightProp != null)
    {
        lightProp.objectReferenceValue = light;
        UnityEngine.Debug.Log($"Set _lightSource = {(light != null ? light.name : "null")}");
    }

    var matProp = so.FindProperty("_shadowMaterial");
    if (matProp != null)
    {
        matProp.objectReferenceValue = shadowMat;
        UnityEngine.Debug.Log($"Set _shadowMaterial = {(shadowMat != null ? shadowMat.name : "null")}");
    }

    so.ApplyModifiedProperties();

    // Force register the Crate's Shadow2DTarget
    var target = UnityEngine.Object.FindObjectOfType<Shadow2DTarget>();
    if (target != null)
    {
        manager.Register(target);
        UnityEngine.Debug.Log($"Registered target: {target.name}");
    }
}

